```typescript
export interface Note {
  readonly id: string;
  readonly heading: string;
  readonly body: string;
  readonly categoryId: string;
}

export interface Category {
  readonly id: string;
  readonly label: string;
}

export async function findNotes(
  notes: readonly Note[],
  query: string,
  loadCategories: () => Promise<readonly Category[]>,
): Promise<Note[]> {
  const categories = await loadCategories();
  const needle = query.trim().toLowerCase();
  const labels = new Map(categories.map(category => [category.id, category.label.toLowerCase()]));
  return notes
    .filter(note =>
      note.heading.toLowerCase().includes(needle) &&
      (note.body.toLowerCase().includes(needle) ||
       (labels.get(note.categoryId)?.includes(needle) ?? false)),
    )
    .map(note => ({ ...note }));
}
```

