import { Note, Category, findNotes } from './solution';

function equal(a: unknown, b: unknown, m = 'values differ'): void { if (a !== b) throw new Error(`${m}: ${String(a)} !== ${String(b)}`); }
function ok(v: unknown, m = 'assertion failed'): asserts v { if (!v) throw new Error(m); }
async function rejects(p: Promise<unknown>): Promise<void> { try { await p; } catch { return; } throw new Error('expected rejection'); }

(async () => {
  const duplicate: Note = { id: '1', heading: 'Alpha Heading', body: 'plain', categoryId: 'c1' };
  const notes: readonly Note[] = [
    duplicate,
    { id: '2', heading: 'other', body: 'contains ALPHA here', categoryId: 'missing' },
    { id: '3', heading: 'other', body: 'plain', categoryId: 'c2' },
    { id: '4', heading: 'other', body: 'plain', categoryId: 'C2' },
    duplicate,
  ];
  const categories: readonly Category[] = [{ id: 'c1', label: 'misc' }, { id: 'c2', label: 'Alpha Group' }];
  let calls = 0;
  const found = await findNotes(notes, '  aLpHa ', async () => { calls++; return categories; });
  equal(calls, 1); equal(found.map(x => x.id).join(','), '1,2,3,1');
  ok(found[0] !== duplicate); ok(found[3] !== duplicate); ok(found[0] !== found[3]);
  (found[0] as any).heading = 'changed'; equal(duplicate.heading, 'Alpha Heading');
  calls = 0; const all = await findNotes(notes, '   ', async () => { calls++; return categories; });
  equal(calls, 1); equal(all.length, notes.length); ok(all !== notes); ok(all[0] !== notes[0]);
  equal(notes.length, 5); equal(categories[1].label, 'Alpha Group');
  calls = 0; await rejects(findNotes(notes, 'x', async () => { calls++; throw new Error('load'); })); equal(calls, 1);
})().catch(error => { throw error; });

